func TestEventBus() throws {
    // -- tagsMatch: containment, kinds, empty --
    let tags = [tagString(Tag.TOPIC, "orders"), tagInt(Tag.KIND, 5)]
    check(tagsMatch(tags, []), "empty filter matches")
    check(tagsMatch(tags, [tagString(Tag.TOPIC, "orders")]), "containment")
    check(tagsMatch(tags, tags), "self match")
    check(!tagsMatch(tags, [tagEnum(Tag.KIND, 5)]), "int != enum")
    check(!tagsMatch(tags, [tagString(Tag.KIND, "5")]), "int != string")
    check(!tagsMatch(tags, [tagString(Tag.TOPIC, "other")]), "value mismatch")

    // -- fan-out honors filters --
    let (broker, client) = setupBus()
    let orders = EventBox()
    let allEvents = EventBox()
    collect(try subscribeEvents(client, [tagString(Tag.TOPIC, "orders")]), orders)
    collect(try subscribeEvents(client, []), allEvents)
    waitFor({ broker.stats()["subscribers"] == 2 }, "2 subscribers")
    check(try publishEvent(client, [tagString(Tag.TOPIC, "orders")],
        bytes("o1"), "test") == 1, "seq 1")
    check(try publishEvent(client, [tagString(Tag.TOPIC, "other")],
        bytes("x1"), "test") == 2, "seq 2")
    waitFor({ orders.count == 1 && allEvents.count == 2 }, "fanout")
    check(text(orders[0].payload) == "o1", "filtered payload")
    check(orders[0].publisherId == "test", "publisher")
    check(allEvents[0].seq == 1 && allEvents[1].seq == 2, "all seqs")

    // -- kinds never cross-match --
    let (broker2, client2) = setupBus()
    let got = EventBox()
    collect(try subscribeEvents(client2, [tagInt(Tag.KIND, 5)]), got)
    waitFor({ broker2.stats()["subscribers"] == 1 }, "kind subscriber")
    _ = try publishEvent(client2, [tagString(Tag.KIND, "5")], bytes("s"), "")
    _ = try publishEvent(client2, [tagEnum(Tag.KIND, 5)], bytes("e"), "")
    check(try publishEvent(client2, [tagInt(Tag.KIND, 5)], bytes("i"), "") == 3,
        "seq 3")
    waitFor({ got.count == 1 }, "kind match")
    check(text(got[0].payload) == "i", "int kind only")

    // (No user-tag pass-through leg: the generated Tag is a
    // closed Swift enum; see Eventbus.swift. Own tags arrive
    // by regenerating from an extended events.proto copy.)

    // -- slow subscriber drops oldest --
    let broker4 = EventBusBroker(queueCapacity: 4)
    let sub = broker4.subscribeLocal([])
    for i in 1...6 { broker4.publishEvent([], bytes("m" + String(i)), "") }
    check(broker4.stats()["dropped"] == 2, "dropped count")
    check(sub.dropped == 2, "sub dropped")
    var seqs: [UInt64] = []
    for _ in 0..<4 { seqs.append(sub.take()!.seq) }
    check(seqs == [3, 4, 5, 6], "kept newest")
    sub.close()
    check(broker4.stats()["subscribers"] == 0, "close unregisters")

    // -- close unsubscribes (RPC) --
    let (broker5, client5) = setupBus()
    let stream = try subscribeEvents(client5, [])
    waitFor({ broker5.stats()["subscribers"] == 1 }, "1 subscriber")
    _ = try publishEvent(client5, [], bytes("a"), "")
    check(text(try stream.Recv().payload) == "a", "recv before close")
    stream.Close()
    _ = try publishEvent(client5, [], bytes("b"), "")
    waitFor({ broker5.stats()["subscribers"] == 0 }, "reaped")

    // -- git log round-trip + idempotent --
    let repo = FileManager.default.temporaryDirectory
        .appendingPathComponent("grpc-dc-eventbus-" + UUID().uuidString).path
    try FileManager.default.createDirectory(atPath: repo,
        withIntermediateDirectories: true)
    let broker6 = EventBusBroker()
    let events = [
        broker6.publishEvent([tagString(Tag.TOPIC, "orders")], bytes("o1"), "test"),
        broker6.publishEvent([tagString(Tag.TOPIC, "other")], bytes("x1"), "test"),
        broker6.publishEvent([tagString(Tag.TOPIC, "orders")], bytes("o2"), "test"),
    ]
    let head1 = try exportEvents(repo, events)
    check(try gitText(repo, ["rev-list", "--count", "grpc-dc-events"]) == "3",
        "commit count")
    check(try exportEvents(repo, events) == head1, "idempotent re-export")
    let imported = try importEvents(repo)
    check(imported.count == 3 && imported[0].seq == 1 && imported[2].seq == 3,
        "import seqs")
    check(text(imported[0].payload) == "o1" && text(imported[2].payload) == "o2",
        "import payloads")
    let filtered = try importEvents(repo, filterTags: [tagString(Tag.TOPIC, "orders")])
    check(filtered.count == 2 && filtered[1].seq == 3, "import filter")
    let window = try importEvents(repo, fromSeq: 1, toSeq: 2)
    check(window.count == 1 && window[0].seq == 2, "import window")

    print("TestEventBus OK")
}
